window.buildWorldThemes=function({scene,material,box,group,scenery,palette,ground,sun,sunlight,shell}){
 const winter=group(),neon=group();scene.add(winter,neon);const trees=[];
 for(const side of [-1,1])for(let n=0;n<16;n++){const g=group(),h=2.4+(n%4)*.6;box(g,0,.8,0,.24,1.6,.24,0x776a6a,false);for(let i=0;i<3;i++){const cone=new THREE.Mesh(new THREE.ConeGeometry(1.0-i*.18,h*.58,9),material(i%2?0xf2f7fc:0x83aab0));cone.position.y=h*.44+i*h*.23;g.add(cone);}g.position.set(side*(8+n%3*2),0,8-n*11);winter.add(g);trees.push(g);}
 for(const side of [-1,1])for(let n=0;n<5;n++){const peak=new THREE.Mesh(new THREE.ConeGeometry(12,25+(n%3)*8,5),material(0xc7dce9));peak.position.set(side*(30+n*7),9,-60-n*16);winter.add(peak);}
 for(const side of [-1,1]){const m=new THREE.Mesh(new THREE.BoxGeometry(.045,.04,180),new THREE.MeshBasicMaterial({color:side<0?0xf18bea:0x64e4e3}));m.position.set(side*4.5,.17,-70);neon.add(m);}
 for(const side of [-1,1])for(let n=0;n<8;n++){const sign=new THREE.Mesh(new THREE.BoxGeometry(.07,1.1,2.7),new THREE.MeshBasicMaterial({color:n%2?0xdc73d9:0x83e5ee}));sign.position.set(side*7.7,4+n%3,4-n*19);neon.add(sign);}
 const starPositions=[];for(let n=0;n<120;n++)starPositions.push((n*37%140)-70,18+(n*13%45),-95-(n*19%65));const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xdde4ff,size:.15,fog:false}));scene.add(stars);
 const flakes=[];for(let n=0;n<260;n++)flakes.push((n*17%40)-20,1+(n*11%27),12-(n*23%140));const flakeGeo=new THREE.BufferGeometry();flakeGeo.setAttribute('position',new THREE.Float32BufferAttribute(flakes,3));const weather=new THREE.Points(flakeGeo,new THREE.PointsMaterial({color:0xf5faff,size:.065,transparent:true,opacity:.7}));scene.add(weather);
 const configs={sunset:{name:'落日城 · 环线',number:'01',sky:'linear-gradient(#737ea9 0%,#c5a3b3 42%,#edbd9f 65%,#867a89 83%,#282d43 100%)',fog:0xb6a3b6,ground:0x665c72,road:0x585368,city:palette,sun:0xffd8b1,light:2.5},neon:{name:'霓虹港 · 夜行',number:'02',sky:'linear-gradient(#141b40 0%,#383766 45%,#71618c 67%,#242845 100%)',fog:0x414565,ground:0x292c48,road:0x343950,city:[0x383c61,0x494d76,0x574567,0x514d70,0x33525b,0x37425e],sun:0xdcdef4,light:1.3},snow:{name:'雪境线 · 森林',number:'03',sky:'linear-gradient(#91b8d5 0%,#bed4e5 48%,#e6edf4 68%,#a1bdcf 100%)',fog:0xc4d9e5,ground:0xebf0f3,road:0xadc0cc,city:palette,sun:0xffefce,light:2.2}};
 let active='sunset';function apply(id){if(!configs[id])return;active=id;const c=configs[id];shell.style.background=c.sky;scene.fog.color.setHex(c.fog);scene.fog.near=id==='snow'?30:38;scene.fog.far=id==='snow'?110:125;ground.material.color.setHex(c.ground);material(0x585368).color.setHex(c.road);palette.forEach((p,n)=>material(p).color.setHex(c.city[n]));material(0xab97a4).color.setHex(id==='snow'?0xe0eaf0:id==='neon'?0x606385:0xab97a4);material(0xc5b2b5).color.setHex(id==='snow'?0xf4f8fc:id==='neon'?0x9092b9:0xc5b2b5);sun.material.color.setHex(c.sun);sun.scale.setScalar(id==='neon'?.45:1);sunlight.intensity=c.light;winter.visible=id==='snow';neon.visible=id==='neon';stars.visible=id==='neon';weather.visible=id!=='sunset';weather.material.size=id==='snow'?.065:.025;weather.material.opacity=id==='snow'?.75:.45;scenery.forEach(p=>p.group.visible=id!=='snow');document.getElementById('map-number').textContent=c.number;document.getElementById('map-name').textContent=c.name;document.querySelectorAll('[data-map]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.map===id)));try{localStorage.setItem('nightline-map-v1',id);}catch{}}
 function update(dt,move){if(active==='snow'){for(const tree of trees){tree.position.z+=move;if(tree.position.z>22)tree.position.z-=180;}}if(active!=='sunset'){const a=flakeGeo.attributes.position.array;for(let n=0;n<a.length;n+=3){a[n+1]-=dt*(active==='snow'?1.8:12);a[n+2]+=move;if(a[n+1]<.2)a[n+1]=28;if(a[n+2]>16)a[n+2]-=148;}flakeGeo.attributes.position.needsUpdate=true;}}
 let saved='sunset';try{const p=localStorage.getItem('nightline-map-v1');if(configs[p])saved=p;}catch{}apply(saved);return{apply,update,get current(){return active;}};
};
